    function Get-Option2AppxPackagesByPattern {
        param([Parameter(Mandatory)][string]$Pattern)

        try {
            @(Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue | Where-Object {
                $_.Name -like $Pattern -or $_.PackageFullName -like $Pattern -or $_.PackageFamilyName -like $Pattern
            })
        }
        catch {
            Write-Option2Log ("Failed to query AppX packages for pattern {0}: {1}" -f $Pattern, $_.Exception.Message) 'WARN'
            @()
        }
    }

    function Get-Option2ProvisionedPackagesByPattern {
        param([Parameter(Mandatory)][string]$Pattern)

        try {
            @(Get-AppxProvisionedPackage -Online -ErrorAction SilentlyContinue | Where-Object {
                $_.DisplayName -like $Pattern -or $_.PackageName -like $Pattern
            })
        }
        catch {
            Write-Option2Log ("Failed to query provisioned packages for pattern {0}: {1}" -f $Pattern, $_.Exception.Message) 'WARN'
            @()
        }
    }

    function Test-Option2ProtectedAppxPackage {
        <#
        .SYNOPSIS
        Returns $true for protected Windows SystemApps that should be reported and skipped.

        .DESCRIPTION
        Some packages match consumer wildcard patterns but are part of Windows and cannot be
        removed with Remove-AppxPackage. Attempting removal generates noisy 0x80073CFA / 0x80070032
        failures. These packages are intentionally preserved and logged as SKIP instead of WARN/ERROR.
        #>
        [CmdletBinding()]
        param(
            [Parameter(Mandatory)]$Package
        )

        $protectedNames = @(
            'Microsoft.XboxGameCallableUI',
            'MicrosoftTeams',
            'MSTeams'
        )

        $name = [string]$Package.Name
        $packageFullName = [string]$Package.PackageFullName
        $installLocation = [string]$Package.InstallLocation
        $signatureKind = [string]$Package.SignatureKind
        $nonRemovable = $false

        try {
            if ($null -ne $Package.NonRemovable) {
                $nonRemovable = [bool]$Package.NonRemovable
            }
        }
        catch {
            $nonRemovable = $false
        }

        if ($protectedNames -contains $name) {
            return $true
        }

        if ($protectedNames | Where-Object { $packageFullName -like ("{0}_*" -f $_) }) {
            return $true
        }

        if ($nonRemovable) {
            return $true
        }

        # Do not broadly remove Windows SystemApps when they are matched only by a wildcard. Many are OS components.
        if ($installLocation -match '^[A-Za-z]:\\Windows\\SystemApps\\') {
            return $true
        }

        return $false
    }

    function Remove-Option2InstalledAppxPackage {
        param(
            [Parameter(Mandatory)]$Package,
            [Parameter(Mandatory)][string]$Pattern
        )

        try {
            if ($PSCmdlet.ShouldProcess($Package.PackageFullName, 'Remove installed AppX package')) {
                Remove-AppxPackage -Package $Package.PackageFullName -ErrorAction Stop
            }
            Write-Option2Log ("Removed installed AppX package: {0}" -f $Package.PackageFullName) 'OK'
            return $true
        }
        catch {
            Write-Option2Log ("Failed to remove installed AppX package {0} matched by {1}: {2}" -f $Package.PackageFullName, $Pattern, $_.Exception.Message) 'WARN'
            return $false
        }
    }

    function Remove-Option2ProvisionedAppxPackage {
        param(
            [Parameter(Mandatory)]$Package,
            [Parameter(Mandatory)][string]$Pattern
        )

        try {
            if ($PSCmdlet.ShouldProcess($Package.PackageName, 'Remove provisioned AppX package')) {
                Remove-AppxProvisionedPackage -Online -PackageName $Package.PackageName -ErrorAction Stop | Out-Null
            }
            Write-Option2Log ("Removed provisioned AppX package: {0}" -f $Package.PackageName) 'OK'
            return $true
        }
        catch {
            Write-Option2Log ("Failed to remove provisioned AppX package {0} matched by {1}: {2}" -f $Package.PackageName, $Pattern, $_.Exception.Message) 'WARN'
            return $false
        }
    }

    function Disable-Option2Copilot {
        [CmdletBinding(SupportsShouldProcess)]
        param()

        Write-Option2Log 'Applying Microsoft Copilot disable and removal controls.' 'INFO'

        # Legacy Windows Copilot policy. Still useful on older Windows 11 builds.
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot' -Name 'TurnOffWindowsCopilot' -Value 1 -Description 'Turn off Windows Copilot for machine' | Out-Null
        Set-Option2RegistryDword -Path 'HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot' -Name 'TurnOffWindowsCopilot' -Value 1 -Description 'Turn off Windows Copilot for current user' | Out-Null

        # WindowsAI policy values used by newer Windows 11 management baselines / CSP-backed policies.
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' -Name 'RemoveMicrosoftCopilotApp' -Value 1 -Description 'Request Microsoft Copilot app removal on supported Windows 11 builds' | Out-Null
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' -Name 'TurnOffWindowsCopilot' -Value 1 -Description 'Turn off Windows Copilot WindowsAI machine policy' | Out-Null
        Set-Option2RegistryDword -Path 'HKCU:\Software\Policies\Microsoft\Windows\WindowsAI' -Name 'RemoveMicrosoftCopilotApp' -Value 1 -Description 'Request Microsoft Copilot app removal for current user on supported Windows 11 builds' | Out-Null
        Set-Option2RegistryDword -Path 'HKCU:\Software\Policies\Microsoft\Windows\WindowsAI' -Name 'TurnOffWindowsCopilot' -Value 1 -Description 'Turn off Windows Copilot WindowsAI current-user policy' | Out-Null

        # Disable newer AI entry points where the policy value exists on supported builds.
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' -Name 'DisableClickToDo' -Value 1 -Description 'Disable Click to Do where supported' | Out-Null
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' -Name 'DisableCocreator' -Value 1 -Description 'Disable Paint Cocreator where supported' | Out-Null
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' -Name 'DisableGenerativeFill' -Value 1 -Description 'Disable Paint generative fill where supported' | Out-Null
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI' -Name 'DisableImageCreator' -Value 1 -Description 'Disable Paint Image Creator where supported' | Out-Null

        # Hide taskbar Copilot button for default/current shell policy paths when present.
        Set-Option2RegistryDword -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'ShowCopilotButton' -Value 0 -Description 'Hide Copilot taskbar button for current user' | Out-Null
        Set-Option2RegistryDword -Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'ShowCopilotButton' -Value 0 -Description 'Hide Copilot taskbar button machine default' | Out-Null

        try {
            $copilotProcesses = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '*Copilot*' })
            foreach ($process in $copilotProcesses) {
                if ($PSCmdlet.ShouldProcess($process.ProcessName, 'Stop Copilot process')) {
                    Stop-Process -Id $process.Id -Force -ErrorAction Stop
                }
                Write-Option2Log ("Stopped Copilot process: {0} ({1})" -f $process.ProcessName, $process.Id) 'OK'
            }
        }
        catch {
            Write-Option2Log ("Failed while stopping Copilot processes: {0}" -f $_.Exception.Message) 'WARN'
        }

        try {
            $copilotTasks = @(Get-ScheduledTask -ErrorAction SilentlyContinue | Where-Object {
                $_.TaskName -like '*Copilot*' -or $_.TaskPath -like '*Copilot*'
            })
            foreach ($task in $copilotTasks) {
                if ($PSCmdlet.ShouldProcess(("{0}{1}" -f $task.TaskPath, $task.TaskName), 'Disable Copilot scheduled task')) {
                    Disable-ScheduledTask -TaskName $task.TaskName -TaskPath $task.TaskPath -ErrorAction Stop | Out-Null
                }
                Write-Option2Log ("Disabled Copilot scheduled task: {0}{1}" -f $task.TaskPath, $task.TaskName) 'OK'
            }
        }
        catch {
            Write-Option2Log ("Failed while disabling Copilot scheduled tasks: {0}" -f $_.Exception.Message) 'WARN'
        }
    }

    $results = [ordered]@{
        PatternsProcessed          = 0
        InstalledPackagesRemoved  = 0
        ProvisionedPackagesRemoved = 0
        InstalledPackagesNotFound = 0
        FailedRemovals            = 0
        CopilotPoliciesApplied     = $false
        RemovedItems              = New-Object System.Collections.Generic.List[string]
        FailedItems               = New-Object System.Collections.Generic.List[string]
        PreservedItems            = New-Object System.Collections.Generic.List[string]
        SkippedProtectedItems     = New-Object System.Collections.Generic.List[string]
        LogPath                   = $logPath
    }

    try {
        Write-Option2Log '=== Option 2 Windows 11 Bloatware and Copilot Removal Started ===' 'INFO'
        Write-Option2Log ("Computer: {0}" -f $env:COMPUTERNAME) 'INFO'
        Write-Option2Log ("Run mode: {0}" -f $(if ($WhatIfPreference) { 'WhatIf / simulation' } else { 'Apply changes' })) 'INFO'

        if (-not $SkipCopilotDisable) {
            Disable-Option2Copilot
            $results.CopilotPoliciesApplied = $true
        }
        else {
            Write-Option2Log 'Copilot disable policy step skipped by parameter.' 'SKIP'
        }

        $patterns = if ($CustomAppList -and $CustomAppList.Count -gt 0) {
            [ordered]@{ 'Custom List' = $CustomAppList }
        }
        else {
            Get-Option2DefaultBloatwarePatterns
        }

        # Explicit safety guard: Client.CBS can contain shell/start/search components and is not removed.
        $results.PreservedItems.Add('MicrosoftWindows.Client.CBS intentionally preserved; only Copilot-specific packages and policies are targeted.') | Out-Null
        $results.PreservedItems.Add('Microsoft Teams intentionally preserved and excluded from Option 2 bloatware removal.') | Out-Null
        Write-Option2Log 'Safety guard active: MicrosoftWindows.Client.CBS is intentionally preserved.' 'INFO'
        Write-Option2Log 'Safety guard active: Microsoft Teams packages are intentionally preserved and excluded from bloatware removal.' 'INFO'
        Write-Option2Log 'Safety guard active: protected Windows SystemApps such as Microsoft.XboxGameCallableUI are skipped instead of treated as failed removals.' 'INFO'

        foreach ($category in $patterns.Keys) {
            Write-Option2Log ("Processing category: {0}" -f $category) 'INFO'

            foreach ($pattern in $patterns[$category]) {
                $results.PatternsProcessed++
                Write-Progress -Activity 'Option 2 - Removing Windows bloatware' -Status ("Processing {0}" -f $pattern) -PercentComplete 0

                $installedPackages = @(Get-Option2AppxPackagesByPattern -Pattern $pattern)
                if ($installedPackages.Count -eq 0) {
                    $results.InstalledPackagesNotFound++
                    Write-Option2Log ("No installed AppX package found for pattern: {0}" -f $pattern) 'SKIP'
                }
                else {
                    foreach ($package in $installedPackages) {
                        if (Test-Option2ProtectedAppxPackage -Package $package) {
                            $message = "Protected Windows SystemApp preserved: {0} matched by {1}" -f $package.PackageFullName, $pattern
                            Write-Option2Log $message 'SKIP'
                            $results.PreservedItems.Add($message) | Out-Null
                            $results.SkippedProtectedItems.Add($package.PackageFullName) | Out-Null
                            continue
                        }

                        if (Remove-Option2InstalledAppxPackage -Package $package -Pattern $pattern) {
                            $results.InstalledPackagesRemoved++
                            $results.RemovedItems.Add($package.PackageFullName) | Out-Null
                        }
                        else {
                            $results.FailedRemovals++
                            $results.FailedItems.Add($package.PackageFullName) | Out-Null
                        }
                    }
                }

                if (-not $SkipProvisionedRemoval) {
                    $provisionedPackages = @(Get-Option2ProvisionedPackagesByPattern -Pattern $pattern)
                    foreach ($package in $provisionedPackages) {
                        if (Remove-Option2ProvisionedAppxPackage -Package $package -Pattern $pattern) {
                            $results.ProvisionedPackagesRemoved++
                            $results.RemovedItems.Add($package.PackageName) | Out-Null
                        }
                        else {
                            $results.FailedRemovals++
                            $results.FailedItems.Add($package.PackageName) | Out-Null
                        }
                    }
                }
                else {
                    Write-Option2Log ("Provisioned package removal skipped for pattern: {0}" -f $pattern) 'SKIP'
                }
            }
        }

        Write-Progress -Activity 'Option 2 - Removing Windows bloatware' -Completed

        try {
            Write-Option2Log 'Refreshing machine and user policy.' 'INFO'
            gpupdate.exe /target:computer /force | Out-Null
            gpupdate.exe /target:user /force | Out-Null
            Write-Option2Log 'Policy refresh requested successfully.' 'OK'
        }
        catch {
            Write-Option2Log ("Policy refresh failed or was unavailable: {0}" -f $_.Exception.Message) 'WARN'
        }

        Write-Host ''
        Write-Host ('=' * 72) -ForegroundColor Cyan
        Write-Host 'OPTION 2 BLOATWARE / COPILOT REMOVAL SUMMARY' -ForegroundColor Cyan
        Write-Host ('=' * 72) -ForegroundColor Cyan
        Write-Host ("Patterns processed             : {0}" -f $results.PatternsProcessed) -ForegroundColor White
        Write-Host ("Installed packages removed     : {0}" -f $results.InstalledPackagesRemoved) -ForegroundColor Green
        Write-Host ("Provisioned packages removed   : {0}" -f $results.ProvisionedPackagesRemoved) -ForegroundColor Green
        Write-Host ("Installed patterns not found   : {0}" -f $results.InstalledPackagesNotFound) -ForegroundColor Yellow
        Write-Host ("Protected packages skipped     : {0}" -f $results.SkippedProtectedItems.Count) -ForegroundColor DarkGray
        Write-Host ("Failed removal attempts        : {0}" -f $results.FailedRemovals) -ForegroundColor $(if ($results.FailedRemovals -gt 0) { 'Red' } else { 'Green' })
        Write-Host ("Copilot policies applied       : {0}" -f $results.CopilotPoliciesApplied) -ForegroundColor Green
        Write-Host ("Log file                       : {0}" -f $logPath) -ForegroundColor Cyan
        Write-Host ('=' * 72) -ForegroundColor Cyan

        if ($results.FailedRemovals -gt 0) {
            $global:LastStatus = "[WARN] Option 2 completed with $($results.FailedRemovals) failed removal attempt(s). See $logPath"
        }
        else {
            $global:LastStatus = "[OK] Option 2 completed. Removed $($results.InstalledPackagesRemoved) installed and $($results.ProvisionedPackagesRemoved) provisioned package(s); Copilot disabled."
        }
    }
    catch {
        Write-Option2Log ("Critical error during Option 2: {0}" -f $_.Exception.Message) 'ERROR'
        $global:LastStatus = "[ERROR] Option 2 failed: $($_.Exception.Message)"
    }
    finally {
        try {
            $script:Option2LogEntries | Out-File -LiteralPath $logPath -Encoding UTF8 -Force
            Write-Host "`nDetailed Option 2 log saved to: $logPath" -ForegroundColor Cyan
        }
        catch {
            Write-Host ("Failed to write Option 2 log: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
        }
    }

    return [pscustomobject]$results
}

# -----------------------------------------------------------------------------
# Option 3 - Recommended Registry Settings
# -----------------------------------------------------------------------------
function Apply-RecommendedRegistrySettings {
    <#
    .SYNOPSIS
    Applies recommended Windows registry settings for privacy, performance, and usability

    .DESCRIPTION
    Configures registry settings to improve system privacy, performance, and user experience.
    Settings are organized by category and applied with comprehensive error handling.

    .PARAMETER SettingsCategory
    Specific category of settings to apply (All, Privacy, Performance, UI, Security, System)

    .PARAMETER BackupRegistry
    Creates a registry backup before applying changes

    .PARAMETER Force
    Applies settings without confirmation prompts

    .OUTPUTS
    Returns hashtable with application results and statistics

    .EXAMPLE
    Apply-RecommendedRegistrySettings

    .EXAMPLE
    Apply-RecommendedRegistrySettings -SettingsCategory Privacy -BackupRegistry

    .EXAMPLE
    Apply-RecommendedRegistrySettings -WhatIf
    #>

    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter()]
        [ValidateSet('All', 'Privacy', 'Performance', 'UI', 'Security', 'System')]
        [string]$SettingsCategory = 'All',

        [Parameter()]
        [switch]$BackupRegistry,

        [Parameter()]
        [switch]$Force
    )

    Write-StatusLog "Configuring Windows registry settings..." -Level "Info"

    # Detect OS version
    $osInfo = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    $isWindows11 = $false
    try {
        $buildNumber = [int]$osInfo.BuildNumber
        if ($buildNumber -ge 22000) {
            $isWindows11 = $true
        }
    } catch {
        $isWindows11 = $true
    }

    # Registry settings organized by category
    $registrySettings = @{
        Privacy = @(
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\DataCollection'; Name = 'AllowTelemetry'; Value = 0; Type = 'DWORD'; Description = 'Disable telemetry collection' },
            @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection'; Name = 'AllowTelemetry'; Value = 0; Type = 'DWORD'; Description = 'Disable telemetry (policy)' },
            @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection'; Name = 'DoNotShowFeedbackNotifications'; Value = 1; Type = 'DWORD'; Description = 'Disable feedback notifications' },
            @{ Path = 'HKCU:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; Name = 'DisableTailoredExperiencesWithDiagnosticData'; Value = 1; Type = 'DWORD'; Description = 'Disable tailored experiences' },
            @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo'; Name = 'DisabledByGroupPolicy'; Value = 1; Type = 'DWORD'; Description = 'Disable advertising ID' },
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting'; Name = 'Disabled'; Value = 1; Type = 'DWORD'; Description = 'Disable error reporting' },
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Sensor\Overrides\{BFA794E4-F964-4FDB-90F6-51056BFE4B44}'; Name = 'SensorPermissionState'; Value = 0; Type = 'DWORD'; Description = 'Disable location sensor' },
            @{ Path = 'HKLM:\SYSTEM\CurrentControlSet\Services\lfsvc\Service\Configuration'; Name = 'Status'; Value = 0; Type = 'DWORD'; Description = 'Disable location services' },
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location'; Name = 'Value'; Value = 'Deny'; Type = 'String'; Description = 'Deny location access' },

            # Winutil-style additions
            @{ Path = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent'; Name = 'DisableWindowsConsumerFeatures'; Value = 1; Type = 'DWORD'; Description = 'Disable consumer features' },
            @{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search'; Name = 'BingSearchEnabled'; Value = 0; Type = 'DWORD'; Description = 'Disable Bing search in Start menu' },
            @{ Path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search'; Name = 'CortanaConsent'; Value = 0; Type = 'DWORD'; Description = 'Disable Cortana search consent' }
        )

        Performance = @(
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'; Name = 'SystemResponsiveness'; Value = 0; Type = 'DWORD'; Description = 'Optimize system responsiveness' },
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'; Name = 'NetworkThrottlingIndex'; Value = 4294967295; Type = 'DWORD'; Description = 'Disable network throttling' },
            @{ Path = 'HKCU:\Control Panel\Desktop'; Name = 'MenuShowDelay'; Value = '200'; Type = 'String'; Description = 'Reduce menu show delay' },
            @{ Path = 'HKCU:\Control Panel\Desktop'; Name = 'AutoEndTasks'; Value = '1'; Type = 'String'; Description = 'Auto-end hung tasks' },
            @{ Path = 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management'; Name = 'ClearPageFileAtShutdown'; Value = 0; Type = 'DWORD'; Description = 'Skip page file clearing' },
            @{ Path = 'HKLM:\SYSTEM\ControlSet001\Services\Ndu'; Name = 'Start'; Value = 2; Type = 'DWORD'; Description = 'Optimize network usage' },
            @{ Path = 'HKCU:\Control Panel\Mouse'; Name = 'MouseHoverTime'; Value = '400'; Type = 'String'; Description = 'Reduce mouse hover time' },
            @{ Path = 'HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters'; Name = 'IRPStackSize'; Value = 30; Type = 'DWORD'; Description = 'Optimize file sharing' },
            @{ Path = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DeliveryOptimization\Config'; Name = 'DODownloadMode'; Value = 1; Type = 'DWORD'; Description = 'Optimize delivery mode' }
        )

        UI = @(
