# Option 12 - Disk Cleanup
# -----------------------------------------------------------------------------
function Run-DiskCleanup {
    <#
    .SYNOPSIS
    Runs an SSD-safe disk cleanup and storage health check.

    .DESCRIPTION
    Cleans common Windows temporary/cache locations, empties the Recycle Bin,
    clears Windows Update and Delivery Optimization download caches, runs DISM
    component cleanup without ResetBase, checks SSD/NVMe wear with
    Get-StorageReliabilityCounter, and alerts the technician when reported wear
    is above the configured threshold.

    This function intentionally does not run traditional defrag against SSD or
    NVMe drives and does not perform secure wiping/free-space wiping because
    those actions add unnecessary writes and can reduce SSD life.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [switch]$SkipSystemCleanup,
        [switch]$SkipTempFolders,
        [switch]$SkipSSDTrim,
        [int]$WearWarningPercent = 10,
        [int]$TimeoutSeconds = 1800,
        [string]$LogPath = (Join-Path (Get-ComptonLogDirectory) ('DiskCleanup_{0}.log' -f (Get-Date -Format 'yyyyMMdd_HHmmss')))
    )

    $previousErrorActionPreference = $ErrorActionPreference
    $previousProgressPreference = $ProgressPreference
    $ErrorActionPreference = 'Continue'
    $ProgressPreference = 'SilentlyContinue'

    $script:DiskCleanupLogEntries = New-Object System.Collections.Generic.List[string]
    $script:DiskCleanupSummary = [ordered]@{
        DeletedItems       = 0
        FailedItems        = 0
        LockedItems        = 0
        AccessDeniedItems  = 0
        SkippedItems       = 0
        CleanupActions     = 0
        WearWarnings       = 0
        ReTrimActions      = 0
        StartTime          = Get-Date
        EndTime            = $null
        LogPath            = $LogPath
    }

    function Write-DiskCleanupLog {
        param(
            [Parameter(Mandatory)][string]$Message,
            [ValidateSet('INFO','OK','WARN','ERROR','SKIP')][string]$Level = 'INFO'
        )

        $timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
        $line = '[{0}] [{1,-5}] {2}' -f $timestamp, $Level, $Message
        [void]$script:DiskCleanupLogEntries.Add($line)

        switch ($Level) {
            'OK'    { Write-Host $line -ForegroundColor Green }
            'WARN'  { Write-Host $line -ForegroundColor Yellow }
            'ERROR' { Write-Host $line -ForegroundColor Red }
            'SKIP'  { Write-Host $line -ForegroundColor DarkYellow }
            default { Write-Host $line -ForegroundColor Cyan }
        }
    }

    function Test-DiskCleanupAdministrator {
        try {
            $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
            $principal = New-Object Security.Principal.WindowsPrincipal($identity)
            return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        }
        catch {
            return $false
        }
    }

    function Show-DiskCleanupTechWarning {
        param(
            [Parameter(Mandatory)][string]$Title,
            [Parameter(Mandatory)][string]$Message
        )

        Write-DiskCleanupLog $Message 'WARN'

        try {
            Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
            [void][System.Windows.Forms.MessageBox]::Show(
                $Message,
                $Title,
                [System.Windows.Forms.MessageBoxButtons]::OK,
                [System.Windows.Forms.MessageBoxIcon]::Warning
            )
            return
        }
        catch {
            Write-DiskCleanupLog ('Windows Forms popup was unavailable: {0}' -f $_.Exception.Message) 'SKIP'
        }

        try {
            $msgExe = Join-Path $env:SystemRoot 'System32\msg.exe'
            if (Test-Path -LiteralPath $msgExe) {
                & $msgExe * /TIME:90 $Message 2>$null | Out-Null
            }
        }
        catch {
            Write-DiskCleanupLog ('msg.exe notification failed: {0}' -f $_.Exception.Message) 'SKIP'
        }
    }

    function Get-FolderSizeBytesSafe {
        param([Parameter(Mandatory)][string]$Path)

        try {
            if (-not (Test-Path -LiteralPath $Path)) { return 0 }
            $total = 0L
            Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object {
                if (-not $_.PSIsContainer) { $total += [int64]$_.Length }
            }
            return $total
        }
        catch {
            return 0
        }
    }

    function Format-BytesHumanReadable {
        param([Int64]$Bytes)

        if ($Bytes -lt 0) { return 'Unknown' }
        if ($Bytes -lt 1KB) { return ('{0:N0} B' -f $Bytes) }
        if ($Bytes -lt 1MB) { return ('{0:N2} KB' -f ($Bytes / 1KB)) }
        if ($Bytes -lt 1GB) { return ('{0:N2} MB' -f ($Bytes / 1MB)) }
        if ($Bytes -lt 1TB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
        return ('{0:N2} TB' -f ($Bytes / 1TB))
    }

    function Get-FileLockOwnerHint {
        <#
        .SYNOPSIS
        Best-effort reporting of processes that may be using a file.

        .DESCRIPTION
        Uses the Windows Restart Manager API to identify processes registered
        against a file path. This is report-only. It intentionally does not stop
        or kill any process because killing a process that owns a temp/cache file
        can corrupt active application state or destabilize Windows services.
        #>
        param([Parameter(Mandatory)][string]$Path)

        if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
            return 'Lock owner check skipped because the item is not a file.'
        }

        try {
            if (-not ('DiskCleanup.RestartManager' -as [type])) {
                Add-Type -ErrorAction Stop -TypeDefinition @'
using System;
using System.Text;
using System.Runtime.InteropServices;

namespace DiskCleanup {
    public static class RestartManager {
        [StructLayout(LayoutKind.Sequential)]
        public struct RM_UNIQUE_PROCESS {
            public int dwProcessId;
            public System.Runtime.InteropServices.ComTypes.FILETIME ProcessStartTime;
        }

        public enum RM_APP_TYPE {
            RmUnknownApp = 0,
            RmMainWindow = 1,
            RmOtherWindow = 2,
            RmService = 3,
            RmExplorer = 4,
            RmConsole = 5,
            RmCritical = 1000
        }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        public struct RM_PROCESS_INFO {
            public RM_UNIQUE_PROCESS Process;
            [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 256)]
            public string strAppName;
            [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)]
            public string strServiceShortName;
            public RM_APP_TYPE ApplicationType;
            public uint AppStatus;
            public uint TSSessionId;
            [MarshalAs(UnmanagedType.Bool)]
            public bool bRestartable;
        }

        [DllImport("rstrtmgr.dll", CharSet = CharSet.Unicode)]
        public static extern int RmStartSession(out uint pSessionHandle, int dwSessionFlags, StringBuilder strSessionKey);

        [DllImport("rstrtmgr.dll", CharSet = CharSet.Unicode)]
        public static extern int RmRegisterResources(uint pSessionHandle, uint nFiles, string[] rgsFilenames, uint nApplications, IntPtr rgApplications, uint nServices, string[] rgsServiceNames);

        [DllImport("rstrtmgr.dll")]
        public static extern int RmGetList(uint dwSessionHandle, out uint pnProcInfoNeeded, ref uint pnProcInfo, [In, Out] RM_PROCESS_INFO[] rgAffectedApps, ref uint lpdwRebootReasons);

        [DllImport("rstrtmgr.dll")]
        public static extern int RmEndSession(uint pSessionHandle);
    }
}
'@
            }

            $sessionHandle = [uint32]0
            $sessionKey = New-Object System.Text.StringBuilder 64
            $startResult = [DiskCleanup.RestartManager]::RmStartSession([ref]$sessionHandle, 0, $sessionKey)
            if ($startResult -ne 0) {
                return ('Restart Manager unavailable. RmStartSession returned {0}.' -f $startResult)
            }

            try {
                $files = [string[]]@($Path)
                $registerResult = [DiskCleanup.RestartManager]::RmRegisterResources($sessionHandle, [uint32]1, $files, [uint32]0, [IntPtr]::Zero, [uint32]0, $null)
                if ($registerResult -ne 0) {
                    return ('Restart Manager could not register file. RmRegisterResources returned {0}.' -f $registerResult)
                }

                $needed = [uint32]0
                $count = [uint32]0
                $rebootReasons = [uint32]0
                [void][DiskCleanup.RestartManager]::RmGetList($sessionHandle, [ref]$needed, [ref]$count, $null, [ref]$rebootReasons)

                if ($needed -eq 0) {
                    return 'No owning process reported by Restart Manager.'
                }

                $count = $needed
                $processInfo = New-Object 'DiskCleanup.RestartManager+RM_PROCESS_INFO[]' $count
                $listResult = [DiskCleanup.RestartManager]::RmGetList($sessionHandle, [ref]$needed, [ref]$count, $processInfo, [ref]$rebootReasons)
                if ($listResult -ne 0) {
                    return ('Restart Manager could not list locking processes. RmGetList returned {0}.' -f $listResult)
                }

                $owners = New-Object System.Collections.Generic.List[string]
                for ($i = 0; $i -lt [int]$count; $i++) {
                    $pid = $processInfo[$i].Process.dwProcessId
                    $appName = $processInfo[$i].strAppName
                    $serviceName = $processInfo[$i].strServiceShortName
                    $appType = $processInfo[$i].ApplicationType.ToString()
                    if ([string]::IsNullOrWhiteSpace($appName)) { $appName = 'Unknown' }
                    if (-not [string]::IsNullOrWhiteSpace($serviceName)) {
                        [void]$owners.Add(('{0} PID {1}, service {2}, type {3}' -f $appName, $pid, $serviceName, $appType))
                    }
                    else {
                        [void]$owners.Add(('{0} PID {1}, type {2}' -f $appName, $pid, $appType))
                    }
                }

                if ($owners.Count -gt 0) {
                    return ($owners -join '; ')
                }

                return 'No owning process reported by Restart Manager.'
            }
            finally {
                if ($sessionHandle -ne 0) {
                    [void][DiskCleanup.RestartManager]::RmEndSession($sessionHandle)
                }
            }
        }
        catch {
            return ('Unable to determine lock owner safely: {0}' -f $_.Exception.Message)
        }
    }

    function Remove-DirectoryContentsSafe {
        [CmdletBinding(SupportsShouldProcess)]
        param(
            [Parameter(Mandatory)][string]$Path,
            [string]$Description = $Path,
            [int]$OlderThanDays = -1
        )

        if (-not (Test-Path -LiteralPath $Path)) {
            Write-DiskCleanupLog ('Path not found, skipping {0}: {1}' -f $Description, $Path) 'SKIP'
            $script:DiskCleanupSummary.SkippedItems++
            return
        }

        Write-DiskCleanupLog ('Cleaning {0}: {1}' -f $Description, $Path) 'INFO'

        $cutoff = $null
        if ($OlderThanDays -ge 0) {
            $cutoff = (Get-Date).AddDays(-[int]$OlderThanDays)
            Write-DiskCleanupLog ('Only removing items older than {0} day(s).' -f $OlderThanDays) 'INFO'
        }

        $items = @()
        try {
            $items = @(Get-ChildItem -LiteralPath $Path -Force -ErrorAction Stop)
        }
        catch {
            Write-DiskCleanupLog ('Failed to enumerate {0}: {1}' -f $Path, $_.Exception.Message) 'WARN'
            $script:DiskCleanupSummary.FailedItems++
            return
        }

        foreach ($item in $items) {
            try {
                if ($null -ne $cutoff -and $item.LastWriteTime -gt $cutoff) {
                    $script:DiskCleanupSummary.SkippedItems++
                    continue
                }

                if ($PSCmdlet.ShouldProcess($item.FullName, 'Remove temporary/cache item')) {
                    Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
                    $script:DiskCleanupSummary.DeletedItems++
                }
            }
            catch {
                $exceptionMessage = $_.Exception.Message
                $isLockedOrInUse = ($exceptionMessage -match 'being used by another process|because it is being used|process cannot access|used by another process|The requested operation cannot be performed on a file with a user-mapped section open')
                $isAccessDenied = ($exceptionMessage -match 'Access to the path .* is denied|UnauthorizedAccessException|access is denied')

                if ($isLockedOrInUse) {
                    $script:DiskCleanupSummary.LockedItems++
                    $script:DiskCleanupSummary.SkippedItems++
                    $ownerHint = Get-FileLockOwnerHint -Path $item.FullName
                    Write-DiskCleanupLog ('Skipped locked/in-use item: {0}' -f $item.FullName) 'SKIP'
                    Write-DiskCleanupLog ('Lock owner hint: {0}' -f $ownerHint) 'INFO'
                }
                elseif ($isAccessDenied) {
                    $script:DiskCleanupSummary.AccessDeniedItems++
                    $script:DiskCleanupSummary.SkippedItems++
                    Write-DiskCleanupLog ('Skipped access-denied item: {0} ({1})' -f $item.FullName, $exceptionMessage) 'SKIP'
                }
                else {
                    Write-DiskCleanupLog ('Failed to remove {0}: {1}' -f $item.FullName, $exceptionMessage) 'WARN'
                    $script:DiskCleanupSummary.FailedItems++
                }
            }
        }

        $script:DiskCleanupSummary.CleanupActions++
    }

    function Invoke-ProcessWithTimeoutSafe {
        <#
        .SYNOPSIS
        Runs an external process with timeout, periodic status updates, and log capture.

        .DESCRIPTION
        DISM StartComponentCleanup can legitimately run for a long time and may appear
        frozen if launched with a simple WaitForExit call. This helper starts the process,
        writes a status line at a regular interval, tracks elapsed time, enforces a timeout,
        and captures stdout/stderr to temporary files so redirected output cannot deadlock
        the process.
        #>
        param(
            [Parameter(Mandatory)][string]$FilePath,
            [string[]]$ArgumentList = @(),
            [int]$TimeoutSeconds = 1800,
            [string]$Description = $FilePath,
            [int]$StatusIntervalSeconds = 30
        )

        $stdoutPath = $null
        $stderrPath = $null

        try {
            if (-not (Test-Path -LiteralPath $FilePath)) {
                Write-DiskCleanupLog ('Process not found for {0}: {1}' -f $Description, $FilePath) 'WARN'
                return $false
            }

            if ($TimeoutSeconds -lt 1) { $TimeoutSeconds = 1800 }
            if ($StatusIntervalSeconds -lt 5) { $StatusIntervalSeconds = 5 }

            $argumentText = ($ArgumentList -join ' ')
            $stdoutPath = Join-Path (Get-ComptonLogDirectory) ('DiskCleanup_{0}_stdout.log' -f ([guid]::NewGuid().ToString('N')))
            $stderrPath = Join-Path (Get-ComptonLogDirectory) ('DiskCleanup_{0}_stderr.log' -f ([guid]::NewGuid().ToString('N')))

            Write-DiskCleanupLog ('Starting {0}: {1} {2}' -f $Description, $FilePath, $argumentText) 'INFO'
            Write-DiskCleanupLog ('{0} can take several minutes. Status will update every {1} seconds until it finishes.' -f $Description, $StatusIntervalSeconds) 'INFO'

            $startInfo = New-Object System.Diagnostics.ProcessStartInfo
            $startInfo.FileName = $FilePath
            $startInfo.Arguments = $argumentText
            $startInfo.UseShellExecute = $false
            $startInfo.CreateNoWindow = $true
            $startInfo.RedirectStandardOutput = $false
            $startInfo.RedirectStandardError = $false

            $process = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -NoNewWindow -PassThru -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -ErrorAction Stop
            $stopwatch = [System.Diagnostics.Stopwatch]::StartNew()
            $lastStatusSeconds = -1

            while (-not $process.HasExited) {
                Start-Sleep -Seconds 1
                $elapsedSeconds = [int][math]::Floor($stopwatch.Elapsed.TotalSeconds)

                if ($elapsedSeconds -ge $TimeoutSeconds) {
                    Write-DiskCleanupLog ('{0} exceeded timeout after {1}. Attempting to stop process ID {2}.' -f $Description, $stopwatch.Elapsed.ToString('hh\:mm\:ss'), $process.Id) 'WARN'
                    try {
                        Stop-Process -Id $process.Id -Force -ErrorAction Stop
                    }
                    catch {
                        Write-DiskCleanupLog ('Failed to stop timed-out process ID {0}: {1}' -f $process.Id, $_.Exception.Message) 'WARN'
                    }
                    return $false
                }

                if ($elapsedSeconds -gt 0 -and ($elapsedSeconds % $StatusIntervalSeconds -eq 0) -and $elapsedSeconds -ne $lastStatusSeconds) {
                    $lastStatusSeconds = $elapsedSeconds
                    Write-DiskCleanupLog ('Still running {0}. Elapsed: {1}. Process ID: {2}.' -f $Description, $stopwatch.Elapsed.ToString('hh\:mm\:ss'), $process.Id) 'INFO'
                }
            }

            $process.WaitForExit()
            $stopwatch.Stop()

            if ($stdoutPath -and (Test-Path -LiteralPath $stdoutPath)) {
                $stdout = (Get-Content -LiteralPath $stdoutPath -Raw -ErrorAction SilentlyContinue)
                if (-not [string]::IsNullOrWhiteSpace($stdout)) {
                    $stdout.Trim() -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object {
                        Write-DiskCleanupLog ([string]$_) 'INFO'
                    }
                }
            }

            if ($stderrPath -and (Test-Path -LiteralPath $stderrPath)) {
                $stderr = (Get-Content -LiteralPath $stderrPath -Raw -ErrorAction SilentlyContinue)
                if (-not [string]::IsNullOrWhiteSpace($stderr)) {
                    $stderr.Trim() -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | ForEach-Object {
                        Write-DiskCleanupLog ([string]$_) 'WARN'
                    }
                }
            }

            if ($process.ExitCode -eq 0) {
                Write-DiskCleanupLog ('Completed {0} successfully. Duration: {1}.' -f $Description, $stopwatch.Elapsed.ToString('hh\:mm\:ss')) 'OK'
                return $true
            }

            Write-DiskCleanupLog ('{0} exited with code {1}. Duration: {2}.' -f $Description, $process.ExitCode, $stopwatch.Elapsed.ToString('hh\:mm\:ss')) 'WARN'
            return $false
        }
        catch {
            Write-DiskCleanupLog ('Failed running {0}: {1}' -f $Description, $_.Exception.Message) 'WARN'
            return $false
        }
        finally {
            foreach ($tempPath in @($stdoutPath, $stderrPath)) {
                if ($tempPath -and (Test-Path -LiteralPath $tempPath)) {
                    try { Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue } catch { }
                }
            }
        }
    }

    function Stop-ServiceForCleanupSafe {
        param(
            [Parameter(Mandatory)][string]$Name,
            [int]$TimeoutSeconds = 15
        )

        try {
            $service = Get-Service -Name $Name -ErrorAction Stop
            if ($service.Status -eq 'Stopped') {
                Write-DiskCleanupLog ('Service already stopped: {0}' -f $Name) 'OK'
                return $true
            }

            Write-DiskCleanupLog ('Stopping service for cleanup: {0}' -f $Name) 'INFO'
            Stop-Service -Name $Name -Force -ErrorAction SilentlyContinue
            $service.WaitForStatus('Stopped', [TimeSpan]::FromSeconds($TimeoutSeconds))
            Write-DiskCleanupLog ('Stopped service: {0}' -f $Name) 'OK'
            return $true
        }
        catch {
            Write-DiskCleanupLog ('Could not stop service {0}: {1}' -f $Name, $_.Exception.Message) 'WARN'
            return $false
        }
    }

    function Start-ServiceForCleanupSafe {
        param([Parameter(Mandatory)][string]$Name)

        try {
            $service = Get-Service -Name $Name -ErrorAction Stop
            if ($service.Status -ne 'Running') {
                Start-Service -Name $Name -ErrorAction Stop
                Write-DiskCleanupLog ('Restarted service: {0}' -f $Name) 'OK'
            }
        }
        catch {
            Write-DiskCleanupLog ('Could not restart service {0}: {1}' -f $Name, $_.Exception.Message) 'WARN'
        }
    }

    function Get-SSDHealthSummary {
        [CmdletBinding()]
        param([int]$WearWarningPercent = 10)

        $results = New-Object System.Collections.Generic.List[object]

        try {
            $physicalDisks = @(Get-PhysicalDisk -ErrorAction Stop)
        }
        catch {
            Write-DiskCleanupLog ('Unable to query physical disks: {0}' -f $_.Exception.Message) 'WARN'
            return $results
        }

        foreach ($physicalDisk in $physicalDisks) {
            $busType = [string]$physicalDisk.BusType
            $mediaType = [string]$physicalDisk.MediaType
            $isSolidState = ($mediaType -match 'SSD') -or ($busType -match 'NVMe')

            if (-not $isSolidState) {
                continue
            }

            $reliability = $null
            try {
                $reliability = $physicalDisk | Get-StorageReliabilityCounter -ErrorAction Stop
            }
            catch {
                Write-DiskCleanupLog ('Storage reliability counters unavailable for {0}: {1}' -f $physicalDisk.FriendlyName, $_.Exception.Message) 'WARN'
            }

            $wear = $null
            $temperature = $null
            $readErrors = $null
            $writeErrors = $null
            $powerOnHours = $null

            if ($null -ne $reliability) {
                $wear = $reliability.Wear
                $temperature = $reliability.Temperature
                $readErrors = $reliability.ReadErrorsTotal
                $writeErrors = $reliability.WriteErrorsTotal
                $powerOnHours = $reliability.PowerOnHours
            }

            $entry = [pscustomobject]@{
                FriendlyName = $physicalDisk.FriendlyName
                SerialNumber = $physicalDisk.SerialNumber
                MediaType    = $mediaType
                BusType      = $busType
                HealthStatus = $physicalDisk.HealthStatus
                OperationalStatus = ($physicalDisk.OperationalStatus -join ', ')
                WearPercent  = $wear
                TemperatureC = $temperature
                ReadErrors   = $readErrors
                WriteErrors  = $writeErrors
                PowerOnHours = $powerOnHours
            }
            [void]$results.Add($entry)

            $wearText = if ($null -ne $wear) { ('{0}%' -f $wear) } else { 'Not reported by device/driver' }
            Write-DiskCleanupLog ('SSD/NVMe health: {0} | Media={1} | Bus={2} | Health={3} | Wear={4}' -f $entry.FriendlyName, $entry.MediaType, $entry.BusType, $entry.HealthStatus, $wearText) 'INFO'

            if ($null -ne $wear -and [int]$wear -gt $WearWarningPercent) {
                $script:DiskCleanupSummary.WearWarnings++
                Show-DiskCleanupTechWarning -Title 'SSD/NVMe Wear Warning' -Message ('SSD/NVMe wear is above {0}% on {1}. Reported wear: {2}%. HealthStatus: {3}. Recommend monitoring/replacement planning.' -f $WearWarningPercent, $entry.FriendlyName, $wear, $entry.HealthStatus)
            }
        }

        if ($results.Count -eq 0) {
            Write-DiskCleanupLog 'No SSD/NVMe disks with available storage metadata were detected.' 'WARN'
        }

        return $results
    }

    function Invoke-SSDReTrimSafe {
        [CmdletBinding(SupportsShouldProcess)]
        param()

        try {
            $disks = @(Get-Disk -ErrorAction Stop | Where-Object { $_.BusType -eq 'NVMe' -or $_.MediaType -eq 'SSD' })
        }
        catch {
            Write-DiskCleanupLog ('Unable to enumerate disks for SSD ReTrim: {0}' -f $_.Exception.Message) 'WARN'
            return
        }

        foreach ($disk in $disks) {
            try {
                $partitions = @(Get-Partition -DiskNumber $disk.Number -ErrorAction SilentlyContinue | Where-Object { $_.DriveLetter })
                foreach ($partition in $partitions) {
                    $driveLetter = [string]$partition.DriveLetter
                    if ([string]::IsNullOrWhiteSpace($driveLetter)) { continue }

                    if ($PSCmdlet.ShouldProcess(('{0}:' -f $driveLetter), 'Run SSD ReTrim only')) {
                        Write-DiskCleanupLog ('Running SSD-safe ReTrim on {0}: drive. No defrag will be run.' -f $driveLetter) 'INFO'
                        try {
                            Optimize-Volume -DriveLetter $driveLetter -ReTrim -Verbose -ErrorAction Stop 4>&1 | ForEach-Object {
                                Write-DiskCleanupLog ([string]$_) 'INFO'
                            }
                            $script:DiskCleanupSummary.ReTrimActions++
                            Write-DiskCleanupLog ('Completed ReTrim on {0}: drive.' -f $driveLetter) 'OK'
                        }
                        catch {
                            Write-DiskCleanupLog ('ReTrim failed on {0}: drive: {1}' -f $driveLetter, $_.Exception.Message) 'WARN'
                        }
                    }
                }
            }
            catch {
                Write-DiskCleanupLog ('Failed processing disk {0}: {1}' -f $disk.Number, $_.Exception.Message) 'WARN'
            }
        }
    }

    function Clear-WindowsUpdateDownloadCacheSafe {
        [CmdletBinding(SupportsShouldProcess)]
        param()

        $services = @('UsoSvc','wuauserv','bits')
        foreach ($serviceName in $services) {
            Stop-ServiceForCleanupSafe -Name $serviceName -TimeoutSeconds 15 | Out-Null
        }

        try {
            Remove-DirectoryContentsSafe -Path (Join-Path $env:SystemRoot 'SoftwareDistribution\Download') -Description 'Windows Update download cache'
        }
        finally {
            foreach ($serviceName in @('bits','wuauserv','UsoSvc')) {
                Start-ServiceForCleanupSafe -Name $serviceName
            }
        }
    }

    try {
        Write-DiskCleanupLog '=== Option 12 SSD-Safe Disk Cleanup Started ===' 'INFO'

        if (-not (Test-DiskCleanupAdministrator)) {
            throw 'Disk cleanup operations require Administrator privileges.'
        }

        $logFolder = Split-Path -Path $LogPath -Parent
        if (-not [string]::IsNullOrWhiteSpace($logFolder) -and -not (Test-Path -LiteralPath $logFolder)) {
            New-Item -Path $logFolder -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
        }

        $systemDrive = $env:SystemDrive
        if ([string]::IsNullOrWhiteSpace($systemDrive)) { $systemDrive = 'C:' }

        $freeBefore = $null
        try {
            $systemVolume = Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $systemDrive) -ErrorAction Stop
            $freeBefore = [int64]$systemVolume.FreeSpace
            Write-DiskCleanupLog ('Free space before cleanup on {0}: {1}' -f $systemDrive, (Format-BytesHumanReadable $freeBefore)) 'INFO'
        }
        catch {
            Write-DiskCleanupLog ('Unable to read starting free space: {0}' -f $_.Exception.Message) 'WARN'
        }

        $healthResults = Get-SSDHealthSummary -WearWarningPercent $WearWarningPercent

        if (-not $SkipTempFolders) {
            $cleanupTargets = @(
                @{ Path = $env:TEMP; Description = 'Current user temporary files'; OlderThanDays = 1 },
                @{ Path = (Join-Path $env:SystemRoot 'Temp'); Description = 'Windows temporary files'; OlderThanDays = 1 },
                @{ Path = (Join-Path $env:SystemRoot 'Prefetch'); Description = 'Windows Prefetch files older than 30 days'; OlderThanDays = 30 },
                @{ Path = (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportArchive'); Description = 'Archived Windows Error Reporting data'; OlderThanDays = 7 },
                @{ Path = (Join-Path $env:ProgramData 'Microsoft\Windows\WER\ReportQueue'); Description = 'Queued Windows Error Reporting data'; OlderThanDays = 7 },
                @{ Path = (Join-Path $env:ProgramData 'Microsoft\Windows\DeliveryOptimization\Cache'); Description = 'Delivery Optimization cache'; OlderThanDays = 1 },
                @{ Path = (Join-Path $env:SystemRoot 'ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'); Description = 'Delivery Optimization service cache'; OlderThanDays = 1 },
                @{ Path = (Join-Path $env:ProgramData 'Microsoft\Windows\Caches'); Description = 'Windows ProgramData cache files'; OlderThanDays = 7 },
                @{ Path = (Join-Path $env:LocalAppData 'Microsoft\Windows\INetCache'); Description = 'Current user INet cache'; OlderThanDays = 1 },
                @{ Path = (Join-Path $env:LocalAppData 'Microsoft\Windows\WebCache'); Description = 'Current user WebCache'; OlderThanDays = 7 }
            )

            foreach ($target in $cleanupTargets) {
                Remove-DirectoryContentsSafe -Path $target.Path -Description $target.Description -OlderThanDays $target.OlderThanDays
            }

            # Clean common browser cache folders for all local user profiles without touching passwords, bookmarks, or profile settings.
            $profileRoot = Join-Path $env:SystemDrive 'Users'
            if (Test-Path -LiteralPath $profileRoot) {
                Get-ChildItem -LiteralPath $profileRoot -Directory -Force -ErrorAction SilentlyContinue | Where-Object {
                    $_.Name -notin @('Default','Default User','Public','All Users')
                } | ForEach-Object {
                    $userProfile = $_.FullName
                    $browserCacheTargets = @(
                        @{ Path = (Join-Path $userProfile 'AppData\Local\Microsoft\Edge\User Data\Default\Cache'); Description = ('Edge cache for {0}' -f $_.Name); OlderThanDays = 1 },
                        @{ Path = (Join-Path $userProfile 'AppData\Local\Microsoft\Edge\User Data\Default\Code Cache'); Description = ('Edge code cache for {0}' -f $_.Name); OlderThanDays = 1 },
                        @{ Path = (Join-Path $userProfile 'AppData\Local\Google\Chrome\User Data\Default\Cache'); Description = ('Chrome cache for {0}' -f $_.Name); OlderThanDays = 1 },
                        @{ Path = (Join-Path $userProfile 'AppData\Local\Google\Chrome\User Data\Default\Code Cache'); Description = ('Chrome code cache for {0}' -f $_.Name); OlderThanDays = 1 },
                        @{ Path = (Join-Path $userProfile 'AppData\Local\Mozilla\Firefox\Profiles'); Description = ('Firefox profile caches for {0}' -f $_.Name); OlderThanDays = -1 }
                    )

                    foreach ($cacheTarget in $browserCacheTargets) {
                        if ($cacheTarget.Description -like 'Firefox*' -and (Test-Path -LiteralPath $cacheTarget.Path)) {
                            Get-ChildItem -LiteralPath $cacheTarget.Path -Directory -ErrorAction SilentlyContinue | ForEach-Object {
                                Remove-DirectoryContentsSafe -Path (Join-Path $_.FullName 'cache2\entries') -Description ('Firefox cache for {0}' -f $_.Name) -OlderThanDays 1
                                Remove-DirectoryContentsSafe -Path (Join-Path $_.FullName 'startupCache') -Description ('Firefox startup cache for {0}' -f $_.Name) -OlderThanDays 7
                            }
                        }
                        else {
                            Remove-DirectoryContentsSafe -Path $cacheTarget.Path -Description $cacheTarget.Description -OlderThanDays $cacheTarget.OlderThanDays
                        }
                    }
                }
            }
        }
        else {
            Write-DiskCleanupLog 'Temporary folder cleanup skipped by parameter.' 'SKIP'
        }

        if (-not $SkipSystemCleanup) {
            Clear-WindowsUpdateDownloadCacheSafe

            try {
                Write-DiskCleanupLog 'Clearing Recycle Bin for all drives.' 'INFO'
                if ($PSCmdlet.ShouldProcess('Recycle Bin', 'Clear all recycle bins')) {
                    Clear-RecycleBin -Force -ErrorAction Stop
                    Write-DiskCleanupLog 'Recycle Bin cleared.' 'OK'
                    $script:DiskCleanupSummary.CleanupActions++
                }
            }
            catch {
                Write-DiskCleanupLog ('Recycle Bin cleanup failed or was not applicable: {0}' -f $_.Exception.Message) 'WARN'
            }

            $dismExe = Join-Path $env:SystemRoot 'System32\dism.exe'
            if (Test-Path -LiteralPath $dismExe) {
                [void](Invoke-ProcessWithTimeoutSafe -FilePath $dismExe -ArgumentList @('/Online','/Cleanup-Image','/StartComponentCleanup') -TimeoutSeconds $TimeoutSeconds -Description 'DISM component store cleanup')
            }
            else {
                Write-DiskCleanupLog 'DISM executable was not found; component cleanup skipped.' 'WARN'
            }

            # Remove old CBS compressed logs only; do not delete active CBS.log.
            Remove-DirectoryContentsSafe -Path (Join-Path $env:SystemRoot 'Logs\CBS') -Description 'Old CBS compressed/log files' -OlderThanDays 14
        }
        else {
            Write-DiskCleanupLog 'System cleanup skipped by parameter.' 'SKIP'
        }

        if (-not $SkipSSDTrim) {
            Invoke-SSDReTrimSafe
        }
        else {
            Write-DiskCleanupLog 'SSD ReTrim skipped by parameter.' 'SKIP'
        }

        $freeAfter = $null
        try {
            $systemVolumeAfter = Get-CimInstance -ClassName Win32_LogicalDisk -Filter ("DeviceID='{0}'" -f $systemDrive) -ErrorAction Stop
            $freeAfter = [int64]$systemVolumeAfter.FreeSpace
            Write-DiskCleanupLog ('Free space after cleanup on {0}: {1}' -f $systemDrive, (Format-BytesHumanReadable $freeAfter)) 'INFO'

            if ($null -ne $freeBefore) {
                $recovered = $freeAfter - $freeBefore
                Write-DiskCleanupLog ('Estimated space recovered: {0}' -f (Format-BytesHumanReadable $recovered)) 'OK'
            }
        }
        catch {
            Write-DiskCleanupLog ('Unable to read ending free space: {0}' -f $_.Exception.Message) 'WARN'
        }

        $script:DiskCleanupSummary.EndTime = Get-Date
        Write-DiskCleanupLog ('Deleted items: {0}; Failed items: {1}; Locked/in-use skipped: {2}; Access-denied skipped: {3}; Total skipped: {4}; SSD wear warnings: {5}; ReTrim actions: {6}' -f $script:DiskCleanupSummary.DeletedItems, $script:DiskCleanupSummary.FailedItems, $script:DiskCleanupSummary.LockedItems, $script:DiskCleanupSummary.AccessDeniedItems, $script:DiskCleanupSummary.SkippedItems, $script:DiskCleanupSummary.WearWarnings, $script:DiskCleanupSummary.ReTrimActions) 'INFO'

        if ($script:DiskCleanupSummary.WearWarnings -gt 0) {
            $global:LastStatus = '[WARN] Option 12 cleanup completed, but one or more SSD/NVMe drives reported wear above the warning threshold.'
        }
        elseif ($script:DiskCleanupSummary.FailedItems -gt 0) {
            $global:LastStatus = ('[WARN] Option 12 cleanup completed with {0} item-level cleanup warning(s). Review {1}.' -f $script:DiskCleanupSummary.FailedItems, $LogPath)
        }
        else {
            $global:LastStatus = ('[OK] Option 12 SSD-safe disk cleanup completed. Locked/in-use temp files skipped: {0}. Review {1}.' -f $script:DiskCleanupSummary.LockedItems, $LogPath)
        }
    }
    catch {
        Write-DiskCleanupLog ('Critical Option 12 failure: {0}' -f $_.Exception.Message) 'ERROR'
        $global:LastStatus = ('[ERROR] Option 12 disk cleanup failed: {0}' -f $_.Exception.Message)
    }
    finally {
        $ErrorActionPreference = $previousErrorActionPreference
        $ProgressPreference = $previousProgressPreference

        try {
            if ($script:DiskCleanupSummary.EndTime -eq $null) {
                $script:DiskCleanupSummary.EndTime = Get-Date
            }
            Write-DiskCleanupLog ('Duration: {0:N2} seconds' -f (($script:DiskCleanupSummary.EndTime) - ($script:DiskCleanupSummary.StartTime)).TotalSeconds) 'INFO'
            Write-DiskCleanupLog '=== Option 12 SSD-Safe Disk Cleanup Completed ===' 'INFO'
            $script:DiskCleanupLogEntries | Out-File -LiteralPath $LogPath -Encoding UTF8 -Force
            Write-Host ''
            Write-Host ('Detailed Option 12 log saved to: {0}' -f $LogPath) -ForegroundColor Cyan
        }
        catch {
            Write-Host ('Failed to write Option 12 log: {0}' -f $_.Exception.Message) -ForegroundColor Yellow
        }
    }
}

