# -----------------------------------------------------------------------------
# Main Loop
# -----------------------------------------------------------------------------
function Main {
    do {
        Clear-Host  # <== Clear screen BEFORE showing the menu
        Show-Menu
        $selection = Read-Host "Select an option"
        try {
        switch ($selection) {
            "1" {
                Clear-Host
                New-MISAdminAccount
                Pause
            }
            "2" {
                Clear-Host
                Remove-BloatwareApps
                Pause
            }
			"3" {
				Clear-Host
				Apply-RecommendedRegistrySettings
				Pause
			}
			"4" {
				Clear-Host
				Optimize-WindowsServices
				Pause
			}
			"5" {
				Clear-Host
				Enable-PowerShellRemotingSafely
				Pause
			}
			"6" {
				Clear-Host
				Configure-AutomaticTimeSync
				Pause
			}
			"7" {
				Clear-Host
				Set-DesktopPowerSettings
				Pause
			}
			"8" {
				Clear-Host
				Start-NetworkOptimization
				Pause
			}
			"9" {
				Clear-Host
				Update-Applications
				Pause
			}
			"10" {
				Clear-Host
				Update-HPDrivers
				Pause
			}
			"11"{
				Clear-Host
				Update-WindowsOS
				Pause
			}
			"12" {
				Clear-Host
				Run-DiskCleanup
				Pause
				}
			"13" {
				Clear-Host
				Invoke-SystemMaintenance
				Pause
			}
			"14" {
				Clear-Host
				Remove-UserProfilesClassroom
				Pause
			}
			"15" {
				Clear-Host
				Write-Host ""
				Write-Host "Enter password for CC-Student auto-login configuration" -ForegroundColor Yellow

				$Password1 = Read-Host "Password" -AsSecureString
				$Password2 = Read-Host "Confirm Password" -AsSecureString

				$Ptr1 = [IntPtr]::Zero
				$Ptr2 = [IntPtr]::Zero

				try {
					if (-not $Password1 -or -not $Password2) {
						Write-Host "No password entered. Operation cancelled." -ForegroundColor Red
					}
					else {
						$Ptr1 = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($Password1)
						$Ptr2 = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($Password2)
						$Plain1 = [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($Ptr1)
						$Plain2 = [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($Ptr2)

						if ([string]::IsNullOrWhiteSpace($Plain1)) {
							Write-Host "No password entered. Operation cancelled." -ForegroundColor Red
						}
						elseif ($Plain1 -ne $Plain2) {
							Write-Host "Passwords do not match. Operation cancelled." -ForegroundColor Red
						}
						else {
							Set-DomainAutoLogin -Password $Password1
						}
					}
				}
				finally {
					if ($Ptr1 -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($Ptr1) }
					if ($Ptr2 -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($Ptr2) }
				}
				Pause
			}
			"16" {
				Clear-Host
				Set-OneDriveAutoLoginPolicy
				Pause
			}
			"17" {
                Clear-Host
                Invoke-TechPostDeployment
                Pause
            }
			"18" {
				Clear-Host
				Run-NetworkDiagnostics
				Pause
			}
			"19" {
				Clear-Host
				Invoke-WindowsUpdateServicesRepair
				Pause
			}
			
            "20" { Clear-Host; Invoke-LabApplicationMaintenance; Pause }
            "21" { Clear-Host; Remove-MicrosoftCopilot; Pause }
			"Q" {
				Clear-Host
				Write-Host "Compton College Tech Utils has exited." -ForegroundColor Cyan
				exit
			}
            default {
                $global:LastStatus = "[ERROR] Invalid selection. Please try again."
                Start-Sleep -Seconds 1
            }
        }
        } catch { $global:LastStatus = "[ERROR] $($_.Exception.Message)"; Write-Host $global:LastStatus -ForegroundColor Red; Pause }
    } while ($true)
}


# Optional HTTPS URLs for resources that are specific to the organization.
# Folder resources must be ZIP archives with their normal contents at the archive root.
$script:TechResourceUrls = @{
    Action1Installer = ''
    PaperCutInstaller = ''
    SharpDriverPackage = ''
    HpBiosConfigPackage = ''
    DellCommandConfigurePackage = ''
    Office2024Configuration = ''
    RepairImage = ''
    RepairSetupMedia = ''
    RepairAdk = ''
}
# Bundled maintenance code: attached versions, module dependencies, and approved repair helper.
# GZip/Base64 packaging is only for transport; SHA256 is verified before staging.
$script:TechMaintenanceBundle = ''


function Initialize-TechMaintenanceBundle {
    $target = Join-Path $env:ProgramData ('ComptonTechUtils\Runs\' + [guid]::NewGuid().ToString('N'))
    New-Item -Path $target -ItemType Directory -Force | Out-Null
    $inputStream = New-Object IO.MemoryStream(,[Convert]::FromBase64String($script:TechMaintenanceBundle))
    $zip = New-Object IO.Compression.GZipStream($inputStream,[IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($zip,[Text.Encoding]::UTF8)
    try { $bundle = $reader.ReadToEnd() | ConvertFrom-Json } finally { $reader.Dispose(); $zip.Dispose(); $inputStream.Dispose() }
    foreach ($property in $bundle.PSObject.Properties) {
        $bytes = [Convert]::FromBase64String($property.Value.Content)
        $sha = [Security.Cryptography.SHA256]::Create()
        try { $hash = ([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() } finally { $sha.Dispose() }
        if ($hash -ne $property.Value.SHA256) { throw "Bundled file hash mismatch: $($property.Name)" }
        $text = [Text.Encoding]::UTF8.GetString($bytes).TrimStart([char]0xFEFF)
        # Point canonical module dependencies at this standalone package, never at C:\Scripts.
        $text = $text.Replace("'C:\Scripts\Maintenance.Framework.psm1'", ("'" + (Join-Path $target 'Maintenance.Framework.psm1') + "'"))
        $text = $text.Replace("'C:\Scripts\Maintenance.Copilot.psm1'", ("'" + (Join-Path $target 'Maintenance.Copilot.psm1') + "'"))
        $text = $text.Replace("-ScriptRoot 'C:\Scripts'", ("-ScriptRoot '" + $target + "'"))
        [IO.File]::WriteAllText((Join-Path $target $property.Name),$text,(New-Object Text.UTF8Encoding($true)))
    }
    $script:TechResourceUrls | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $target 'ResourceUrls.json') -Encoding UTF8
    return $target
}

function Invoke-TechMaintenanceScript {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$ScriptName,[hashtable]$Parameters=@{})
    $folder = Initialize-TechMaintenanceBundle
    try {
        . (Join-Path $folder 'Standalone.Support.ps1')
        $resources = Join-Path $folder 'Resources'
        if ($ScriptName -eq '05_Weekend_HP_Drivers_Update.ps1') {
            # HPIA, DCU and .NET retain their official-vendor Internet fallbacks.
            foreach ($name in @('HpiaSourceFolder','HpiaInstallerSharePath','DellCommandUpdateSharePath','DotNetDesktopRuntimeSharePath')) {
                $default = switch ($name) {
                    HpiaSourceFolder {'C:\ProgramData\ComptonTechUtils\Resources\HPImageAssistant'}
                    HpiaInstallerSharePath {'C:\ProgramData\ComptonTechUtils\Resources\HPImageAssistant.exe'}
                    DellCommandUpdateSharePath {'C:\ProgramData\ComptonTechUtils\Resources\Dell-Command-Update-Windows-Universal-Application.exe'}
                    DotNetDesktopRuntimeSharePath {'C:\ProgramData\ComptonTechUtils\Resources\windowsdesktop-runtime-8.0.25-win-x64.exe'}
                }
                $path = if ($Parameters.ContainsKey($name)) { $Parameters[$name] } else { $default }
                if (-not (Test-TechShareAccess -Path $path)) { $Parameters[$name] = Join-Path $resources ('Unavailable-' + $name) }
            }
            $hp = Resolve-TechResource -Key HpBiosConfigPackage -SharePath 'C:\ProgramData\ComptonTechUtils\Resources\HP_Bios_Config' -Destination (Join-Path $resources 'HP_Bios_Config') -Folder -Optional
            $dell = Resolve-TechResource -Key DellCommandConfigurePackage -SharePath 'C:\ProgramData\ComptonTechUtils\Resources\Dell\Command Configure' -Destination (Join-Path $resources 'DellCommandConfigure') -Folder -Optional
            $Parameters.HpBiosConfigShare = if ($hp) {$hp} else {Join-Path $resources 'Unavailable-HP-BIOS'}
            $Parameters.DellCommandConfigureShare = if ($dell) {$dell} else {Join-Path $resources 'Unavailable-Dell-Configure'}
        }
        if ($ScriptName -eq 'Post-Deployment.ps1') {
            $Parameters.CopilotModuleSharePath = Join-Path $folder 'Maintenance.Copilot.psm1'
            foreach ($name in @('DellCommandUpdateSharePath','DotNetDesktopRuntimeSharePath')) {
                $share = if ($name -eq 'DellCommandUpdateSharePath') { 'C:\ProgramData\ComptonTechUtils\Resources\Dell-Command-Update-Windows-Universal-Application.exe' } else { 'C:\ProgramData\ComptonTechUtils\Resources\windowsdesktop-runtime-8.0.25-win-x64.exe' }
                if (-not (Test-TechShareAccess -Path $share)) { $Parameters[$name] = Join-Path $resources ('Unavailable-' + $name) }
            }
        }
        if ($ScriptName -eq '08_System_Repair.ps1') {
            $Parameters.ComponentStoreRepairScriptPath = Join-Path $folder 'Repair-Windows-ComponentStore.ps1'
            if (-not $Parameters.ContainsKey('HpImageAssistantSourcePath')) { $Parameters.HpImageAssistantSourcePath = 'C:\ProgramData\ComptonTechUtils\Resources\HPImageAssistant' }
            if (-not (Test-TechShareAccess -Path $Parameters.HpImageAssistantSourcePath)) { $Parameters.HpImageAssistantSourcePath = Join-Path $resources 'Unavailable-HPIA' }
            if ($Parameters.AllowComponentStoreEscalation) {
                # The attached script still requires its valid n8n approval and private key.
                if (-not $Parameters.ContainsKey('ComponentStoreImagePath')) { $Parameters.ComponentStoreImagePath = Resolve-TechResource -Key RepairImage -SharePath 'C:\ProgramData\ComptonTechUtils\Resources\Installers\25H2\sources\install.wim' -Destination (Join-Path $resources 'install.wim') }
                if (-not $Parameters.ContainsKey('ComponentStoreSetupMediaPath')) { $Parameters.ComponentStoreSetupMediaPath = Resolve-TechResource -Key RepairSetupMedia -SharePath 'C:\ProgramData\ComptonTechUtils\Resources\Installers\25H2' -Destination (Join-Path $resources 'SetupMedia') -Folder }
                if (-not $Parameters.ContainsKey('ComponentStoreAdkPath')) { $Parameters.ComponentStoreAdkPath = Resolve-TechResource -Key RepairAdk -SharePath 'C:\ProgramData\ComptonTechUtils\Resources\Installers\ADK\Deployment Tools' -Destination (Join-Path $resources 'ADK') -Folder -Optional }
            }
        }
        # Each script executes in its own 64-bit Windows PowerShell process.
        # This isolates exit statements, strict mode, duplicate functions, and preferences from the menu.
        $parameterFile = Join-Path $folder 'Invocation.clixml'
        $Parameters | Export-Clixml -LiteralPath $parameterFile
        $runner = @'
param([string]$ScriptName)
$ErrorActionPreference = 'Stop'
try {
    . (Join-Path $PSScriptRoot 'Standalone.Support.ps1')
    $script:TechResourceUrls = Get-Content (Join-Path $PSScriptRoot 'ResourceUrls.json') -Raw | ConvertFrom-Json | Convert-TechMap
    $parameters = Import-Clixml (Join-Path $PSScriptRoot 'Invocation.clixml')
    & (Join-Path $PSScriptRoot $ScriptName) @parameters
}
catch {
    # Render the original exception before the parent cleans the staging folder.
    [Console]::Error.WriteLine(($_ | Format-List * -Force | Out-String))
    [Console]::Error.WriteLine("Position: " + $_.InvocationInfo.PositionMessage)
    [Console]::Error.WriteLine("Script stack: " + $_.ScriptStackTrace)
    [Console]::Error.WriteLine("Exception: " + $_.Exception.ToString())
    exit 1
}
'@
        # Run service enablement separately so its exit cannot terminate the update runner.
        $runnerPath = Join-Path $folder 'Run-Standalone.ps1'
        [IO.File]::WriteAllText($runnerPath,$runner,(New-Object Text.UTF8Encoding($true)))
        $exe = if ([Environment]::Is64BitOperatingSystem -and -not [Environment]::Is64BitProcess) { Join-Path $env:SystemRoot 'Sysnative\WindowsPowerShell\v1.0\powershell.exe' } else { Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe' }
        if ($ScriptName -eq '06_Weekend_Windows_Updates.ps1') {
            & $exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $folder '01_Enable_Windows_Update_Services.ps1')
            if ($LASTEXITCODE -ne 0) { throw "Windows Update service enablement failed: $LASTEXITCODE" }
        }
        $launcherLogRoot = Join-Path $env:ProgramData 'ComptonTechUtils\Logs'
        New-Item -Path $launcherLogRoot -ItemType Directory -Force -ErrorAction Stop | Out-Null
        $logBase = Join-Path $launcherLogRoot ('{0}-{1}-{2}' -f
            [IO.Path]::GetFileNameWithoutExtension($ScriptName),
            (Get-Date -Format 'yyyyMMdd-HHmmss'),[guid]::NewGuid().ToString('N'))
        $stdoutPath = $logBase + '.stdout.log'
        $stderrPath = $logBase + '.stderr.log'
        # Create permanent logs before invoking any child code. These also capture
        # parser/module/bootstrap failures that precede maintenance initialization.
        [IO.File]::WriteAllText($stdoutPath,'')
        [IO.File]::WriteAllText($stderrPath,'')
        Write-Host "Launcher logs: $stdoutPath ; $stderrPath" -ForegroundColor Cyan
        $childArguments = '-NoProfile -ExecutionPolicy Bypass -File "{0}" -ScriptName "{1}"' -f $runnerPath,$ScriptName
        $process = Start-Process -FilePath $exe -ArgumentList $childArguments -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -ErrorAction Stop
        try { $code = $process.ExitCode } finally { $process.Dispose() }
        Get-Content -LiteralPath $stdoutPath -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ }
        Get-Content -LiteralPath $stderrPath -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ -ForegroundColor Red }
        if ($code -notin @(0,1641,3010)) { throw "$ScriptName failed with exit code $code. Error details: $stderrPath ; output: $stdoutPath" }
        $global:LastStatus = "[OK] $ScriptName completed (exit $code). Logs: C:\Logs."
        return [pscustomobject]@{Success=$true;ExitCode=$code;ScriptName=$ScriptName}
    }
    catch {
        $global:LastStatus = "[ERROR] $ScriptName : $($_.Exception.Message)"
        Write-Host $global:LastStatus -ForegroundColor Red
        throw
    }
    finally { Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue }
}

function Invoke-LabApplicationMaintenance {
    [CmdletBinding()]
    param(
    # Reinstall Elastic Agent even if an existing installation is healthy.
    [switch]$ForceElasticAgentReinstall
)
    Invoke-TechMaintenanceScript -ScriptName '04_Sunday_Lab_Application_Maintenance.ps1' -Parameters $PSBoundParameters
}

function Remove-MicrosoftCopilot {
    [CmdletBinding(SupportsShouldProcess = $true, ConfirmImpact = 'Medium')]
    param()
    $folder = Initialize-TechMaintenanceBundle
    $module = $null
    try {
        $module = Import-Module -Name (Join-Path $folder 'Maintenance.Copilot.psm1') -Force -DisableNameChecking -PassThru -ErrorAction Stop
        $result = Invoke-ComprehensiveCopilotRemoval -WhatIf:$WhatIfPreference -Logger {
            param($Message, $Level)
            $color = switch -Regex ([string]$Level) {
                '^(?i:error|failed)$' { 'Red'; break }
                '^(?i:warn|warning)$' { 'Yellow'; break }
                default { 'Cyan' }
            }
            Write-Host ("[{0}] {1}" -f $Level, $Message) -ForegroundColor $color
        }
        $result | Format-List | Out-Host
        if ($WhatIfPreference) { $global:LastStatus = '[INFO] Copilot removal preview completed.' }
        elseif ([int]$result.Failures -gt 0) {
            $global:LastStatus = "[ERROR] Copilot removal reported $($result.Failures) failure(s). Review the results above."
        }
        else { $global:LastStatus = "[OK] Copilot removal completed. Status=$($result.Status); reboot required=$($result.RebootRequired)." }
        Write-Host $global:LastStatus -ForegroundColor Yellow
    }
    finally {
        if ($module) { Remove-Module -ModuleInfo $module -Force -ErrorAction SilentlyContinue }
        Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-TechPostDeployment {
    [CmdletBinding()]
    param()
    Invoke-TechMaintenanceScript -ScriptName 'Post-Deployment.ps1' -Parameters @{
        LocalScriptsPath = 'C:\Scripts'
        RebootWhenComplete = $false
    }
}

# -----------------------------------------------------------------------------
# Entry Point
# -----------------------------------------------------------------------------
# Standalone: startup never downloads or replaces this reviewed script.
Main
